namespace TypeModeling.Analyzers.Generation.Union;

/// <summary>.NET 11 より前の target に足す、C# 15 の union の型の source</summary>
/// <remarks>Embedded 属性により他の assembly から見えないので、assembly ごとに足しても衝突しない</remarks>
internal static class UnionPolyfillSource
{
    /// <summary>生成 source の hint 名</summary>
    internal const string HintName = "TypeModeling.UnionPolyfill.g.cs";

    /// <summary>UnionAttribute と IUnion の定義</summary>
    internal const string Text = """
        // <auto-generated/>
        #nullable enable
        #if !NET11_0_OR_GREATER
        namespace System.Runtime.CompilerServices
        {
            /// <summary>C# 15 の union 型を示す属性</summary>
            [global::Microsoft.CodeAnalysis.Embedded]
            [global::System.AttributeUsage(global::System.AttributeTargets.Class | global::System.AttributeTargets.Struct, AllowMultiple = false, Inherited = false)]
            internal sealed class UnionAttribute : global::System.Attribute
            {
            }

            /// <summary>union の内容を実行時に参照する interface</summary>
            [global::Microsoft.CodeAnalysis.Embedded]
            internal interface IUnion
            {
                /// <summary>union が持つ case の値</summary>
                object? Value { get; }
            }
        }
        #endif
        """;
}
